command:
@'
{
  "$schema": "https://biomejs.dev/schemas/1.9.4/schema.json",
  "organizeImports": { "enabled": true },
  "formatter": {
    "enabled": true,
    "indentStyle": "space",
    "indentWidth": 2
  },
  "linter": {
    "enabled": true,
    "rules": {
      "recommended": true
    }
  }
}
'@ | Set-Content -Path biome.json -Encoding utf8

@'
import { defineConfig } from "vitest/config";
export default defineConfig({ test: { globals: true } });
'@ | Set-Content -Path vitest.config.ts -Encoding utf8

mkdir -p build/obj 2>&1; cat > /tmp/include_check.cpp << 'EOF'
#include "atomdb/storage/LocalFileStorageProvider.hpp"
int main() { LocalFileStorageProvider p; return 0; }
EOF
g++ -std=c++2b -Wall -Wextra -Wpedantic -Werror -Iincludes -c /tmp/include_check.cpp -o build/obj/include_check.obj 2>&1

cat > build/test_pager.cpp << 'EOF'
#include "atomdb/storage/Pager.hpp"
#include <iostream>
int main() {
    try {
        atomdb::Pager p("build/test_direct.db");
        std::cout << "opened, pageCount=" << p.pageCount() << std::endl;
    } catch (const std::exception& e) {
        std::cout << "exception: " << e.what() << std::endl;
    }
}
EOF
g++ -std=c++2b -Wall -Wextra -Wpedantic -Werror -Iincludes build/test_pager.cpp src/Pager.cpp -o build/test_pager.exe 2>&1
./build/test_pager.exe 2>&1 || build/test_pager.exe 2>&1

echo "INSERT users { id:1, name:nikhil, age:30 }
INSERT users { id:2, name:alice, age:25 }
SELECT users
SELECT users WHERE age = 25
EXIT" | & "build/example_01.exe"

"INSERT users { id:1, name:persisted }
SELECT users
EXIT" | & "build/example_02.exe"

Remove-Item -LiteralPath "example_03.atoms" -Force -ErrorAction SilentlyContinue; g++ -std=c++2b -Wall -Wextra -Iincludes -pthread src/SqlParser.cpp example/03_caching_wrapper.cpp -o build/example_03.exe build/src/BTree.obj build/src/Pager.obj 2>&1; if ($LASTEXITCODE -eq 0) { echo "INSERT users { id:1, name:nikhil }
SELECT users WHERE id = 1
SELECT users WHERE id = 1
EXIT" | & "build/example_03.exe" }

g++ -std=c++2b -Wall -Wextra -Iincludes -pthread src/SqlParser.cpp example/04_sharded_storage.cpp -o build/example_04.exe build/src/BTree.obj build/src/Pager.obj 2>&1; if ($LASTEXITCODE -eq 0) { echo "INSERT users { id:1, name:alice }
INSERT users { id:2, name:bob }
INSERT users { id:3, name:carol }
INSERT users { id:4, name:dave }
INSERT users { id:5, name:eve }
INSERT users { id:6, name:frank }
INSERT users { id:7, name:grace }
INSERT users { id:8, name:heidi }
SELECT users
EXIT" | & "build/example_04.exe" }

g++ -std=c++2b -Wall -Wextra -Iincludes -pthread src/SqlParser.cpp example/04_sharded_storage.cpp -o build/example_04.exe build/src/BTree.obj build/src/Pager.obj 2>&1; if ($LASTEXITCODE -eq 0) { echo "INSERT users { id:1, name:alice }
INSERT users { id:2, name:bob }
INSERT users { id:3, name:carol }
INSERT users { id:4, name:dave }
INSERT users { id:5, name:eve }
INSERT users { id:6, name:frank }
INSERT users { id:7, name:grace }
INSERT users { id:8, name:heidi }
SELECT users
EXIT" | & "build/example_04.exe" }

Remove-Item -LiteralPath "example_04_shard_*.atoms" -Force -ErrorAction SilentlyContinue; g++ -std=c++2b -Wall -Wextra -Iincludes -pthread src/SqlParser.cpp example/04_sharded_storage.cpp -o build/example_04.exe build/src/BTree.obj build/src/Pager.obj 2>&1; if ($LASTEXITCODE -eq 0) { echo "INSERT users { id:1, name:alice }
INSERT users { id:2, name:bob }
SELECT users
INSERT users { id:5, name:eve }
SELECT users
EXIT" | & "build/example_04.exe" 2>&1 }
